   124|/** Parse a non-negative whole-USD amount, or null if absent/invalid. */
   125|export function normalizeAmount(value: unknown): number | null {
   126|  if (value === null || value === undefined || value === '') return null;
   127|  const n = typeof value === 'number' ? value : Number(String(value).replace(/[$,\s]/g, ''));
   128|  if (!Number.isFinite(n) || n < 0) return null;
   129|  return Math.round(n);
