   132|/** Normalize an ISO-ish date string to an ISO string, or null if absent/invalid. */
   133|export function normalizeDate(value: unknown): string | null {
   134|  const v = asTrimmedString(value);
   135|  if (!v) return null;
   136|  const time = Date.parse(v);
   137|  if (!Number.isFinite(time)) return null;
   138|  return new Date(time).toISOString();
