   141|/** Compute the remaining capital gap from requested + committed. */
   142|export function computeRemainingGap(requested: number | null, committed: number | null): number | null {
   143|  if (requested === null) return null;
   144|  const gap = requested - (committed ?? 0);
   145|  return Math.max(0, Math.round(gap));
