   274|/** Create a new pipeline entry. Returns the validation error on failure. */
   275|export async function createPipelineEntry(
   276|  input: CreatePipelineInput,
   277|): Promise<{ ok: true; entry: PipelineEntry } | { ok: false; error: string }> {
   278|  const validation = validateCreatePipeline(input);
   279|  if (!validation.ok) return validation;
   280|  const items = await readJsonFile<PipelineEntry[]>(STATE, []);
   281|  const record = buildEntry(input);
   282|  items.push(record);
   283|  await writeJsonFile(STATE, items);
   284|  await appendEvent({ type: 'create', entry: record, at: record.createdAt });
   285|  return { ok: true, entry: record };
