   287|
   288|/** Update an existing pipeline entry. Returns null if not found. */
   289|export async function updatePipelineEntry(id: string, patch: UpdatePipelineInput): Promise<PipelineEntry | null> {
   290|  const items = await readJsonFile<PipelineEntry[]>(STATE, []);
   291|  const index = items.findIndex((item) => item.id === id);
   292|  if (index === -1) return null;
   293|  const prior = items[index]!;
   294|  const merged = buildEntry({ ...prior, ...patch, source: patch.source ?? prior.source, name: patch.name ?? prior.name }, prior);
   295|  items[index] = merged;
   296|  await writeJsonFile(STATE, items);
   297|  await appendEvent({ type: 'update', entryId: id, entry: merged, at: merged.updatedAt });
